// Included within Window.
 void updateRoleBadges(){
  qDeleteAll(roleBadges);roleBadges.clear();if(logicalView||printing||selectionIds.size()!=1)return;
  auto r=model.get(selection);if(!r||r->kind!="relation")return;
  auto badge=[&](QString entity,QString role,int offset){auto node=nodes.value(entity);if(!node)return;auto b=new RoleBadge(role,node);b->setPos(-node->size.width()/2+offset,-node->size.height()/2-25);b->setData(0,r->id);b->setToolTip(richTip(t("Ruolo ","Role ")+role+" · "+model.get(entity)->name+t("\nCorrisponde al ruolo nel pannello Proprietà della relazione selezionata.","\nMatches the role in the selected relationship’s Properties panel.")));roleBadges<<b;};
  badge(r->a,"A",0);badge(r->b,"B",r->a==r->b?28:0);
 }
 QString workflowText()const{
  return t("<h3>Dal disegno alle tabelle del database</h3><p>Questo percorso ti accompagna nella costruzione di un database. Parti dalle informazioni che vuoi rappresentare, organizzale in tabelle e infine prepara le istruzioni SQL per il programma che userai. Puoi esercitarti aprendo <b>Esempi → Ordini</b>.</p><h3>1 · Descrivi la situazione nel concettuale</h3><p>Crea un’entità per ogni gruppo di oggetti che vuoi descrivere, per esempio Ordine e RigaOrdine. Seleziona un’entità e premi <b>Ins</b> per aggiungere i suoi attributi. Indica quali attributi permettono di riconoscere un elemento senza confonderlo con gli altri: sono il suo identificatore.</p><p>Collega le entità con un’associazione. Nelle proprietà indica quante volte ciascuna può partecipare: per esempio, una riga appartiene a un solo ordine, mentre un ordine può contenere più righe. Quando selezioni l’associazione, i quadratini <b>A</b> e <b>B</b> ti aiutano a riconoscere i due ruoli.</p><p>Puoi scegliere un tipo generale, come Intero, Data o Stringa, senza occuparti ancora dei tipi SQL. Per gli importi usa Valuta. Conferma i valori con <b>Applica modifiche</b> e premi <b>F7</b> per controllare il modello. Chen e UML-like mostrano le stesse informazioni con due disegni diversi.</p><h3>2 · Trasforma il modello in tabelle</h3><p>Premi <b>Genera logico</b>. Nel riepilogo puoi vedere quali tabelle verranno create e come saranno collegate. La <b>chiave primaria</b> (PK) distingue le righe di una tabella; una <b>chiave esterna</b> (FK) permette di collegarle a un’altra tabella. Un’associazione molti a molti richiede una tabella che raccolga gli abbinamenti.</p><p>Nell’esempio Ordini, la tabella RigaOrdine riceve il numero dell’ordine a cui appartiene. Questo numero, insieme al numero della riga, ne forma la chiave primaria. Leggi il riepilogo e premi <b>Applica traduzione</b>.</p><p>Nel logico puoi modificare nomi e tipi delle colonne. <b>Mostra origine</b> ti riporta all’elemento concettuale da cui provengono. Se in seguito cambi il concettuale, premi <b>Aggiorna logico</b> e controlla le modifiche proposte prima di applicarle.</p><h3>3 · Prepara il codice SQL</h3><p>Premi <b>F8</b> oppure scegli <b>3 · Fisico/SQL</b>. Seleziona HSQLDB 1.8, MySQL 8.4 o MariaDB 10.11 in base al database che userai. Controlla i tipi delle colonne: per una stringa scegli la lunghezza massima; per un numero reale indica se ti serve un valore decimale esatto, come un importo, oppure approssimato, come una misura.</p><p>Premi <b>Genera SQL</b> per leggere le istruzioni che creano le tabelle e i loro collegamenti. Puoi modificarle, copiarle o salvarle in un file. L’applicazione prepara il codice: per creare le tabelle devi eseguirlo nel programma che gestisce il database.</p><p>Con HSQLDB di LibreOffice Base, apri un database HSQLDB esistente e usa <b>Strumenti → SQL</b>. Con MySQL o MariaDB, indica il nome del database e scegli se crearlo insieme alle tabelle.</p><h3>Salva il lavoro e controlla il risultato</h3><p>Usa <b>Ctrl+S</b> per conservare il progetto nel file <b>.schema</b>, compresi i diversi livelli e le note. Da <b>File → Esporta PDF</b> puoi stampare o condividere il diagramma.</p><p>Leggi anche <b>Cosa resta da controllare</b>: alcune regole richiedono verifiche ulteriori. Per esempio, una chiave esterna può impedire che una riga faccia riferimento a un ordine inesistente, ma non obbliga ogni ordine ad avere almeno una riga.</p>",
"<h3>From a diagram to database tables</h3><p>This guide takes you through building a database. Start with the information you need to describe, organise it into tables, then prepare SQL instructions for your database program. To follow an example, open <b>Examples → Orders</b>.</p><h3>1 · Describe the situation in the conceptual model</h3><p>Create an entity for each group of things you want to describe, such as orders and order lines. Select an entity and press <b>Insert</b> to add its attributes. Mark the attributes that distinguish one item from every other item: together they form its identifier.</p><p>Connect the entities with a relationship. In Properties, specify how many times each entity can take part. For example, a line belongs to one order, while an order can contain several lines. When you select a relationship, the <b>A</b> and <b>B</b> badges help you identify its two roles.</p><p>You may choose a general type, such as Integer, Date or String, without choosing an SQL type yet. Use Money for amounts. Confirm the values with <b>Apply changes</b> and press <b>F7</b> to check the model. Chen and UML-like display the same information in different ways.</p><h3>2 · Turn the model into tables</h3><p>Click <b>Generate logical</b>. The summary shows which tables will be created and how they will be connected. A <b>primary key</b> (PK) distinguishes each row in a table; a <b>foreign key</b> (FK) connects it to another table. A many-to-many relationship needs a table to store the pairs.</p><p>In the Orders example, the order-line table receives the number of the order it belongs to. This number and the line number form its primary key. Read the summary and click <b>Apply mapping</b>.</p><p>You can then edit column names and types. Use <b>Show source</b> to return to the conceptual element they came from. If you later edit the conceptual model, click <b>Update logical</b> and review the proposed changes before applying them.</p><h3>3 · Prepare the SQL code</h3><p>Press <b>F8</b> or choose <b>3 · Physical/SQL</b>. Select HSQLDB 1.8, MySQL 8.4 or MariaDB 10.11 to match your database. Check the column types: choose a maximum length for strings and decide whether real numbers should be exact decimals, such as amounts, or approximate values, such as measurements.</p><p>Click <b>Generate SQL</b> to read the instructions that create the tables and their links. You can edit, copy or save them to a file. The application prepares the code; to create the tables, run it in the program that manages your database.</p><p>For HSQLDB in LibreOffice Base, open an existing HSQLDB database and choose <b>Tools → SQL</b>. For MySQL or MariaDB, enter the database name and choose whether to create it along with the tables.</p><h3>Save your work and check the result</h3><p>Press <b>Ctrl+S</b> to save the project as a <b>.schema</b> file, including its different levels and notes. Use <b>File → Export PDF</b> to print or share the diagram.</p><p>Also read <b>What still needs checking</b>: some rules need further checks. For example, a foreign key can prevent a line from referring to a missing order, but it does not require every order to have at least one line.</p>");
 }
 QDialog *workflowDialog(){
  auto dialog=new QDialog(this);dialog->setObjectName("workflowDialog");dialog->setWindowTitle(t("Come procedere","How to proceed"));auto layout=new QVBoxLayout(dialog);auto browser=new QTextBrowser;browser->setObjectName("workflowText");browser->setHtml(colorHelpHtml(workflowText()));layout->addWidget(browser);auto buttons=new QDialogButtonBox(QDialogButtonBox::Close);auto validateButton=buttons->addButton(t("Verifica concettuale (F7)","Validate conceptual model (F7)"),QDialogButtonBox::ActionRole);connect(validateButton,&QPushButton::clicked,dialog,[this]{validate();});connect(buttons,&QDialogButtonBox::rejected,dialog,&QDialog::reject);layout->addWidget(buttons);dialog->resize(760,660);return dialog;
 }
 void workflow(){QScopedPointer<QDialog> dialog(workflowDialog());dialog->exec();}
